    // Linear index to (n, c_out, d_out, h_out, w_out)
    // -------------------------------------------------------------------------
    .reg .u32 %tmp, %out_idx;
    mov.u32 %out_idx, %idx;          // copy

    // w_out = idx % W_out
    rem.u32.u32 %tmp, %out_idx, %w_out;
    mov.u32 %w_out, %tmp;
    div.u32.u32 %out_idx, %out_idx, %w_out;

    // h_out = idx % H_out
    rem.u32.u32 %tmp, %out_idx, %h_out;
    mov.u32 %h_out, %tmp;
    div.u32.u32 %out_idx, %out_idx, %h_out;

    // d_out = idx % D_out
    rem.u32.u32 %tmp, %out_idx, %d_out;
    mov.u32 %d_out, %tmp;
    div.u32.u32 %out_idx, %out_idx, %d_out;

    // c_out = idx % C_out
    rem.u32.u32 %tmp, %out_idx, %c_out;
    mov.u32 %c_out, %tmp;
    div.u32.u32 %out_idx, %out_idx, %c_out;

    // n = idx
    mov.u32 %n, %out_idx;

    // -------------------------------------------------------------------------
    // Compute convolution sum
    // -------------------------------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f00000000;   // zero

    .reg .u32 %ic, %kd, %kh, %kw;
    .reg .s32 %in_d, %in_h, %in_w;
    .reg .u64 %in_offset, %w_offset, %bias_offset, %out_offset;
    .reg .half %val_h, %wgt_h;

    // Loop over input channels
    mov.u32 %ic, 0;
IC_LOOP:
    setp.ge.u32 %p0, %ic, %c_in;
    @%p0 bra IC_END;

    // Loop over kernel depth
    mov.u32 %kd, 0;
KD_LOOP:
    setp.ge.u32 %p1, %kd, %k;
    @%p1 bra KD_END;

    // Loop over kernel height
    mov.u32 %kh, 0;
KH_LOOP:
    setp.ge.u32 %p2, %kh, %k;
    @%p2 bra KH_END;

    // Loop over kernel width
    mov.u32 %kw, 0;
KW_LOOP:
    setp.ge.u32 %p3, %kw, %k;
    @%p3 bra KW_END;

    // Compute input coordinate
    // in_d = d_out*stride - padding + kd*dilation
    mul.lo.u32 %in_d, %d_out, %s;
    sub.s32 %in_d, %in_d, %p;
    mad.lo.s32 %in_d, %kd, %dil, %in_d;

    // in_h = h_out*stride - padding + kh*dilation
    mul.lo.u32 %in_h, %h_out, %s;
    sub.s32 %in_h, %in_h, %p;
    mad.lo.s32 %in_h, %kh, %dil, %in_h;

    // in_w = w_out*stride - padding + kw*dilation
    mul.lo.u32 %in_w, %w_out, %s;
    sub.s32 %in_w, %in_w, %p;
    mad.lo.s32 %in_w, %kw, %dil, %in_w;

    // Bounds check
    setp.lt.u32 %p4, %in_d, %d_in;
    setp.ge.u32 %p5, %in_h, %h_in;
    setp.ge.u32 %p6, %in_w, %w_in;
    or.pred %p7, %p4, %p5;
    or.pred %p7, %p7, %p6;
    @%p7 bra SKIP;   // out‑of‑bounds => contribution is zero

    // Compute flat offsets
    // input offset = ((n*C_in + ic)*D_in + in_d)*H_in*W_in + in_h*W_in + in_w
    mul.lo.u32 %tmp, %n, %c_in;
    add.u32 %tmp, %tmp, %ic;
    mul.lo.u64 %in_offset, %tmp, %d_in;
    add.u64 %in_offset, %in_offset, %in_d;
    mul.lo.u64 %in_offset, %in_offset, %h_in;
    mul.lo.u64 %tmp, %in_h, %w_in;
    add.u64 %in_offset, %in_offset, %tmp;
    add.u64 %in_offset, %in_offset, %in_w;
    mul.wide.u32 %in_offset, %in_offset, 2;   // sizeof(half)=2

    // weight offset = ((c_out*C_in + ic)*K + kd)*K*K + kh*K + kw
    mul.lo.u32 %tmp, %c_out, %c_in;
    add.u32 %tmp, %tmp, %ic;
    mul.lo.u64 %w_offset, %tmp, %k;
    add.u64 %w_offset, %w_offset, %kd;
    mul.lo.u64 %w_offset, %w_offset, %k;
    add.u64 %w_offset, %w_offset, %kh;
    mul.lo.u64 %w_offset, %w_offset, %k;
    add.u64 %w_offset, %w_offset, %kw;
    mul.wide.u32 %w_offset, %w_offset, 2;     // sizeof(half)=2

    // Load input and weight (half)
    ld.global.f16 %val_h, [%inp + %in_offset];
    ld.global.f16 %wgt_h, [%wgt + %w_offset];

    // Convert to float and accumulate
    cvt.f32.f16 %val_f, %val_h;
    cvt.f32.f16 %wgt_f, %wgt_h;
    fma.rn.f32 %sum, %val_f, %wgt_f, %sum;

SKIP:
    // Increment kw
    add.u32 %kw, %kw, 1;
    bra KW_LOOP;
KW_END:

    // Increment kh
    add.u32 %kh, %kh, 1;
    bra KH_LOOP;
KH_END:

    // Increment kd
    add.u32 %kd, %kd, 1;
    bra KD_LOOP;
KD_END:

    // Increment ic
    add.u32 %ic, %ic, 1;
    bra IC_LOOP;
IC_END:

    // Add bias if present
    setp.ne.u64 %p8, %bias, 0;
    @%p8 {
        mul.lo.u32 %tmp, %c_out, 1;          // bias is 1‑D [C_out]
        mul.wide.u32 %bias_offset, %tmp, 2; // half size
        ld.global.f16 %val_h, [%bias + %bias_offset];
        cvt.f32.f16 %val_f, %val_h;
        add.f32 %sum, %sum, %val_f;
    }

    // Write result (store as half)
    cvt.rn.f16.f32 %val_h, %sum;
    // output offset = ((n*C_out + c_out)*D_out + d_out)*H_out*W_out + h_out*W_out + w_out
    mul.lo.u32 %tmp, %n, %c_out;
    add.u32 %tmp, %tmp, %c_out;
    mul.lo.u64 %out_offset, %tmp, %d_out;
    add.u64 %out_offset, %out_offset, %d_out;
    mul.lo.u64 %out_offset, %out_offset, %h_out;
    mul.lo.u64 %tmp, %h_out, %w_out;
    add.u64 %out_offset, %out_offset, %tmp;
    add.u64 %out_offset, %out_offset, %w_out;
    mul.wide.u32 %out_offset, %out_offset, 2;
    st.global.f16 [%out + %out_offset], %val_h;

DONE:
    ret;
}
'''

# -------------------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel.
# -------------------------------------------------------------------------
class ModelNew:
    """
    Drop‑in replacement for the reference Model.
    Performs a 3‑D convolution using the above PTX kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        # Store convolution hyper‑parameters
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias

        # Load PTX module
        self.module = ptx_load(PTX_SOURCE)

        # Allocate weight (and optional bias) tensors on the GPU
        weight_shape = (out_channels, in_channels // groups,
                        kernel_size, kernel_size, kernel_size)
        self.weight = torch.randn(weight_shape, dtype=torch.float16,
                                  device='cuda')
        if bias:
            self.bias_tensor = torch.randn(out_channels,
                                           dtype=torch.float16,
                                           device='cuda')
        else:
            self.bias_tensor = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Input shape: (N, C_in, D, H, W)
        N, C_in, D_in, H_in, W_in = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        DIL = self.dilation

        # Compute output dimensions (same as nn.Conv3d)
        D_out = (D_in + 2 * P - DIL * (K - 1) - 1) // S + 1
        H_out = (H_in + 2 * P - DIL * (K - 1) - 1) // S + 1
        W_out = (W_in + 2 * P - DIL * (K - 1) - 1) // S + 1

        out = torch.empty((N, self.out_channels, D_out, H_out, W_out),
                          dtype=torch.float16, device='cuda')

        total_out_elements = out.numel()

        # Launch configuration (1‑D grid)
        threads_per_block = 256
        blocks = (total_out_elements + threads_per_block - 1) // threads_per_block

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            0 if self.bias_tensor is None else self.bias_tensor.data_ptr(),
            out.data_ptr(),
            N,
            C_in,
            self.out_channels,
            D_in,
            H_in,
            W_in,
            K,
            S,
            P,
            DIL,
            total_out_elements
        ]

        ptx_launch(self.module, "conv3d_fp16", (blocks,), (threads_per_block,), args)

        return out
